// CSD_RATIONALE_BEGIN
// Root cause (from diagnostics): "Visible span token length: avg 1.60, median 1.00"
// and "Examples with only tiny valid visible spans: 38/49".
// The arithmetic expression grammar accepts a single number/identifier as a
// complete parse, so CloseSpanIfComplete fires after just 1 token (e.g.,
// <<1>> instead of <<n1 * frac + n2>>).
//
// Primary fix: Add a minimum-token-before-close guard (minTokensBeforeClose = 5).
// In each constrained loop, run ConstrainedStep / SafeBoostedConstrainedStep
// for at least 5 iterations WITHOUT calling CloseSpanIfComplete. Only after
// 5+ tokens does Phase 2B switch to the CloseSpanIfComplete + ConstrainedStep
// pattern. This prevents premature single-token closure.
//
// Secondary fix: Use SafeBoostedConstrainedStep with operator tokens (+,-,*,/)
// during the forced minimum phase. After a variable token, the grammar allows
// both operators (continuation) and EOS (stop). Boosting operators makes the
// model prefer multi-term expressions.
//
// Tertiary fix: Guidance removes "keep short" (which encouraged 1-token answers)
// and instead says "include ALL relevant variables".
//
// Quaternary fix: RenderedEndsWith replaces forbidden literal next == "<<" in Phase 4.
//
// Structure preserved from attempt 11 (best: 2% accuracy, 100% syntax):
// Phase 1: UnconstrainedChunk watching for <<
// Phase 2A: Forced min-tokens constrained (no close check), operator-boosted
// Phase 2B: CloseSpanIfComplete + ConstrainedStep loop
// Phase 3: CloseSpanWithinBudget fallback
// Phase 4: More unconstrained steps if no span yet
// Phase 5A/5B: Second pass with same min-token structure
// Phase 6: CloseSpanWithinBudget
// Phase 7: Force open + min-tokens + close
// Phase 8: Final safety CloseSpanWithinBudget
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   Phase 1 (UnconstrainedChunk): insideConstrainedOut stays false until stoppedOnOpen;
//     EnterObservedConstrainedSpan sets currentConstrainedOut := [] which is valid
//     by precondition parser.IsValidPrefix([]).
//   Phase 2A (minTokens forced loop): SafeBoostedConstrainedStep/ConstrainedStep returns
//     a parser-valid token or EOS; AppendConstrainedToken appends only parser-valid
//     tokens, preserving IsValidPrefix; EOS breaks without appending.
//   Phase 2B (close+generate loop): CloseSpanIfComplete either closes
//     (insideConstrainedOut := false, implication vacuous, currentConstrainedOut := [])
//     or costs 0 and leaves state unchanged. On the else path, ConstrainedStep +
//     AppendConstrainedToken preserves IsValidPrefix as in Phase 2A.
//   Phase 3 / 6 / 8 (CloseSpanWithinBudget): postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   Phase 4 (UnconstrainedStep): insideConstrainedOut stays false until
//     RenderedEndsWith(generated, "<<"); EnterObservedConstrainedSpan sets
//     currentConstrainedOut := [].
//   Phases 5A/5B: same arguments as Phases 2A/2B.
//   Phase 7: OpenConstrainedSpan sets currentConstrainedOut := [] (valid);
//     nested Phase 7A/7B loops same as Phase 2A/2B; CloseSpanWithinBudget same as Phase 3.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: UnconstrainedChunk postcondition: |cg| <= |generated| + stepsUsed;
//     we add stepsUsed to steps, preserving the bound.
//   Phase 2A: Each iteration increments steps by 1 and |generated| by at most 1
//     (AppendConstrainedToken on non-EOS, 0 on EOS break). Bound preserved.
//   Phase 2B: closed path: steps+1, |generated|+<=1 (">>" close token). Else path:
//     steps+1, |generated|+<=1 (one appended token or EOS). Both preserve bound.
//   Phase 3/6/8: CloseSpanWithinBudget: |wg| <= |generated| + spanBudget;
//     we add spanBudget to steps.
//   Phase 4: UnconstrainedStep: steps+1, |generated|+<=1.
//   Phase 5A/5B: same as Phase 2A/2B.
//   Phase 7 prefix: OpenConstrainedSpan: steps+1, |generated|+1 (the << token).
//     Phase 7A/7B nested loops: same as Phase 2A/2B.
//     CloseSpanWithinBudget: same as Phase 3.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve this problem step by step. At the very end write: The answer is <<EXPR>> where EXPR is a complete arithmetic formula using ALL the relevant variable names from the problem (without braces), combined with operators +, -, *, /, (, ), and integer literals. The formula must include multiple variables - never write just a single number or single variable. Use all key quantities from the problem. Example: The answer is <<n * price - discount + tax>>. No LaTeX, no {}, no **, no backslashes.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var hasCompletedSpan: bool := false;
var chunkSize: nat := 40;
var innerStepLimit: nat := 80;
var minTokensBeforeClose: nat := 5;
var operatorTokens := ["*", "+", "-", "/", "(", ")"];

var phase1Limit: nat := (maxSteps * 75) / 100;
if phase1Limit == 0 && maxSteps > 0 {
  phase1Limit := 1;
}

// Phase 1: Unconstrained generation in chunks watching for "<<" opening delimiter
while steps < phase1Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var actualChunk := chunkSize;
  if steps + actualChunk > phase1Limit {
    actualChunk := phase1Limit - steps;
  }
  if actualChunk == 0 {
    break;
  }
  var cg, stoppedOnOpen, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(lm, prompt, generated, actualChunk, "<<", eosToken);
  generated := cg;
  steps := steps + stepsUsed;
  if stoppedOnEos {
    break;
  }
  if stoppedOnOpen {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// Phase 2A: Force minimum tokens in constrained span before allowing close
// (operator-boosted to encourage multi-term expressions)
var innerSteps: nat := 0;

while insideConstrainedOut && steps < maxSteps && innerSteps < minTokensBeforeClose
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases minTokensBeforeClose - innerSteps
{
  var constrainedPromptA := prompt + generated[..|generated| - |currentConstrainedOut|];
  var nextA := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPromptA, currentConstrainedOut, operatorTokens, 2.0, eosToken);
  steps := steps + 1;
  innerSteps := innerSteps + 1;
  if nextA == eosToken {
    break;
  } else {
    var agA, aiA, acA := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nextA);
    generated := agA;
    insideConstrainedOut := aiA;
    currentConstrainedOut := acA;
  }
}

// Phase 2B: Constrained generation with CloseSpanIfComplete (after minimum tokens)
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps
{
  var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed {
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    steps := steps + 1;
    innerSteps := innerSteps + 1;
    if next == eosToken {
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 3: If span still open after inner loop, use CloseSpanWithinBudget to close it
if insideConstrainedOut && steps < maxSteps {
  var spanBudget: nat := 60;
  var remaining := maxSteps - steps;
  if spanBudget > remaining {
    spanBudget := remaining;
  }
  if spanBudget > 0 {
    var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget);
    generated := wg;
    insideConstrainedOut := wi;
    currentConstrainedOut := wc;
    steps := steps + spanBudget;
    if !insideConstrainedOut {
      hasCompletedSpan := true;
    }
  }
}

// Phase 4: If no span completed, continue free generation watching for "<<"
while steps < phase1Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// Phase 5A: Force minimum tokens in second-pass constrained span (operator-boosted)
var innerSteps2: nat := 0;

while insideConstrainedOut && steps < maxSteps && innerSteps2 < minTokensBeforeClose
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases minTokensBeforeClose - innerSteps2
{
  var constrainedPrompt5a := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next5a := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt5a, currentConstrainedOut, operatorTokens, 2.0, eosToken);
  steps := steps + 1;
  innerSteps2 := innerSteps2 + 1;
  if next5a == eosToken {
    break;
  } else {
    var ag5a, ai5a, ac5a := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next5a);
    generated := ag5a;
    insideConstrainedOut := ai5a;
    currentConstrainedOut := ac5a;
  }
}

// Phase 5B: Second-pass constrained generation with CloseSpanIfComplete
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps2 < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps2
{
  var cg2, ci2, cc2, closed2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed2 {
    generated := cg2;
    insideConstrainedOut := ci2;
    currentConstrainedOut := cc2;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    var constrainedPrompt2 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next2 := helpers.ConstrainedStep(lm, parser, constrainedPrompt2, currentConstrainedOut, eosToken);
    steps := steps + 1;
    innerSteps2 := innerSteps2 + 1;
    if next2 == eosToken {
      break;
    } else {
      var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
      generated := ag2;
      insideConstrainedOut := ai2;
      currentConstrainedOut := ac2;
    }
  }
}

// Phase 6: If still open, use CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var spanBudget2: nat := 60;
  var remaining2 := maxSteps - steps;
  if spanBudget2 > remaining2 {
    spanBudget2 := remaining2;
  }
  if spanBudget2 > 0 {
    var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget2);
    generated := wg2;
    insideConstrainedOut := wi2;
    currentConstrainedOut := wc2;
    steps := steps + spanBudget2;
    if !insideConstrainedOut {
      hasCompletedSpan := true;
    }
  }
}

// Phase 7: If no span completed, force one open and close within remaining budget
if !insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  if steps + 2 <= maxSteps {
    var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
    generated := fg;
    insideConstrainedOut := fi;
    currentConstrainedOut := fc;
    steps := steps + 1;

    // Phase 7A: Force minimum tokens (operator-boosted)
    var innerSteps3: nat := 0;

    while insideConstrainedOut && steps < maxSteps && innerSteps3 < minTokensBeforeClose
      invariant 0 <= steps <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases minTokensBeforeClose - innerSteps3
    {
      var constrainedPrompt7a := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next7a := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt7a, currentConstrainedOut, operatorTokens, 2.0, eosToken);
      steps := steps + 1;
      innerSteps3 := innerSteps3 + 1;
      if next7a == eosToken {
        break;
      } else {
        var ag7a, ai7a, ac7a := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next7a);
        generated := ag7a;
        insideConstrainedOut := ai7a;
        currentConstrainedOut := ac7a;
      }
    }

    var innerLimit3: nat := innerStepLimit;

    // Phase 7B: Close + generate loop
